6|# Three.js Post-Processing
7|
8|## Quick Start
9|
10|```javascript
11|import * as THREE from "three";
12|import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
13|import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
14|import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
15|
16|// Setup composer
17|const composer = new EffectComposer(renderer);
18|
19|// Render scene
20|const renderPass = new RenderPass(scene, camera);
21|composer.addPass(renderPass);
22|
23|// Add bloom
24|const bloomPass = new UnrealBloomPass(
25|  new THREE.Vector2(window.innerWidth, window.innerHeight),
26|  1.5, // strength
27|  0.4, // radius
28|  0.85, // threshold
29|);
30|composer.addPass(bloomPass);
31|
32|// Animation loop - use composer instead of renderer
33|function animate() {
34|  requestAnimationFrame(animate);
35|  composer.render(); // NOT renderer.render()
36|}
37|```
