70|## Common Effects
71|
72|### Bloom (Glow)
73|
74|```javascript
75|import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
76|
77|const bloomPass = new UnrealBloomPass(
78|  new THREE.Vector2(window.innerWidth, window.innerHeight),
79|  1.5, // strength - intensity of glow
80|  0.4, // radius - spread of glow
81|  0.85, // threshold - brightness threshold
82|);
83|
84|composer.addPass(bloomPass);
85|
86|// Adjust at runtime
87|bloomPass.strength = 2.0;
88|bloomPass.threshold = 0.5;
89|bloomPass.radius = 0.8;
90|```
91|
92|### Selective Bloom
93|
94|Apply bloom only to specific objects.
95|
96|```javascript
97|import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
98|import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
99|
100|// Layer setup
101|const BLOOM_LAYER = 1;
102|const bloomLayer = new THREE.Layers();
103|bloomLayer.set(BLOOM_LAYER);
104|
105|// Mark objects to bloom
106|glowingMesh.layers.enable(BLOOM_LAYER);
107|
108|// Dark material for non-blooming objects
109|const darkMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });
110|const materials = {};
111|
112|function darkenNonBloomed(obj) {
113|  if (obj.isMesh && !bloomLayer.test(obj.layers)) {
114|    materials[obj.uuid] = obj.material;
115|    obj.material = darkMaterial;
116|  }
117|}
118|
119|function restoreMaterial(obj) {
120|  if (materials[obj.uuid]) {
121|    obj.material = materials[obj.uuid];
122|    delete materials[obj.uuid];
123|  }
124|}
125|
126|// Custom render loop
127|function render() {
128|  // Render bloom pass
129|  scene.traverse(darkenNonBloomed);
130|  composer.render();
131|  scene.traverse(restoreMaterial);
132|
133|  // Render final scene over bloom
134|  renderer.render(scene, camera);
135|}
136|```
