147|  1 / window.innerHeight,
148|);
149|
150|composer.addPass(fxaaPass);
151|
152|// Update on resize
153|function onResize() {
154|  fxaaPass.material.uniforms["resolution"].value.set(
155|    1 / window.innerWidth,
156|    1 / window.innerHeight,
157|  );
158|}
