332|## Custom ShaderPass
333|
334|Create your own post-processing effects.
335|
336|```javascript
337|import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
338|
339|const CustomShader = {
340|  uniforms: {
341|    tDiffuse: { value: null }, // Required: input texture
342|    time: { value: 0 },
343|    intensity: { value: 1.0 },
344|  },
345|  vertexShader: `
346|    varying vec2 vUv;
347|
348|    void main() {
349|      vUv = uv;
350|      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
351|    }
352|  `,
353|  fragmentShader: `
354|    uniform sampler2D tDiffuse;
355|    uniform float time;
356|    uniform float intensity;
357|    varying vec2 vUv;
358|
359|    void main() {
360|      vec2 uv = vUv;
361|
362|      // Wave distortion
363|      uv.x += sin(uv.y * 10.0 + time) * 0.01 * intensity;
364|
365|      vec4 color = texture2D(tDiffuse, uv);
366|      gl_FragColor = color;
367|    }
368|  `,
369|};
370|
371|const customPass = new ShaderPass(CustomShader);
372|composer.addPass(customPass);
373|
374|// Update in animation loop
375|customPass.uniforms.time.value = clock.getElapsedTime();
376|```
377|
378|### Invert Colors Shader
379|
380|```javascript
381|const InvertShader = {
382|  uniforms: {
383|    tDiffuse: { value: null },
384|  },
385|  vertexShader: `
386|    varying vec2 vUv;
387|    void main() {
388|      vUv = uv;
389|      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
390|    }
391|  `,
392|  fragmentShader: `
393|    uniform sampler2D tDiffuse;
394|    varying vec2 vUv;
395|
396|    void main() {
397|      vec4 color = texture2D(tDiffuse, vUv);
398|      gl_FragColor = vec4(1.0 - color.rgb, color.a);
399|    }
400|  `,
401|};
402|```
403|
404|### Chromatic Aberration
405|
406|```javascript
407|const ChromaticAberrationShader = {
408|  uniforms: {
409|    tDiffuse: { value: null },
410|    amount: { value: 0.005 },
411|  },
412|  vertexShader: `
413|    varying vec2 vUv;
414|    void main() {
415|      vUv = uv;
416|      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
417|    }
418|  `,
419|  fragmentShader: `
420|    uniform sampler2D tDiffuse;
421|    uniform float amount;
422|    varying vec2 vUv;
423|
424|    void main() {
425|      vec2 dir = vUv - 0.5;
426|      float dist = length(dir);
427|
428|      float r = texture2D(tDiffuse, vUv - dir * amount * dist).r;
429|      float g = texture2D(tDiffuse, vUv).g;
430|      float b = texture2D(tDiffuse, vUv + dir * amount * dist).b;
431|
432|      gl_FragColor = vec4(r, g, b, 1.0);
433|    }
434|  `,
435|};
436|```
