438|## Combining Multiple Effects
439|
440|```javascript
441|import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
442|import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
443|import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
444|import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
445|import { FXAAShader } from "three/addons/shaders/FXAAShader.js";
446|import { VignetteShader } from "three/addons/shaders/VignetteShader.js";
447|import { GammaCorrectionShader } from "three/addons/shaders/GammaCorrectionShader.js";
448|
449|const composer = new EffectComposer(renderer);
450|
451|// 1. Render scene
452|composer.addPass(new RenderPass(scene, camera));
453|
454|// 2. Bloom
455|const bloomPass = new UnrealBloomPass(
456|  new THREE.Vector2(window.innerWidth, window.innerHeight),
457|  0.5,
458|  0.4,
459|  0.85,
460|);
461|composer.addPass(bloomPass);
462|
463|// 3. Vignette
464|const vignettePass = new ShaderPass(VignetteShader);
465|vignettePass.uniforms["offset"].value = 0.95;
466|vignettePass.uniforms["darkness"].value = 1.0;
467|composer.addPass(vignettePass);
468|
469|// 4. Gamma correction
470|composer.addPass(new ShaderPass(GammaCorrectionShader));
471|
472|// 5. Anti-aliasing (always last before output)
473|const fxaaPass = new ShaderPass(FXAAShader);
474|fxaaPass.uniforms["resolution"].value.set(
475|  1 / window.innerWidth,
476|  1 / window.innerHeight,
477|);
478|composer.addPass(fxaaPass);
479|```
